From 8d59c48acc468dddffa92dbb44ce2d614f1fafbc Mon Sep 17 00:00:00 2001
From: Wilke Schwiedop <drwilly@drwilly.de>
Date: Fri, 11 Oct 2013 21:17:49 +0200
Subject: [PATCH] fixes error introduced in
 d51fc41b90784f71454c2478d153dab9b53ae690


diff --git a/src/executor.c b/src/executor.c
index c75d831..d29af3f 100644
--- a/src/executor.c
+++ b/src/executor.c
@@ -73,6 +73,8 @@ exec(const Ast *ast) {
 	case N_DECLARATION:
 		declaration(ast);
 		return;
+	case N_FUNCTION:
+		return;
 	case N_RETURN:
 		returnstat(ast);
 		return;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the lack of handling for the `N_FUNCTION` case in the `exec` function, which resulted in improper execution flow when a function node was encountered in the abstract syntax tree (AST). This omission likely led to unexpected behavior or errors during the execution of function declarations.

        Commit message:
        fixes error introduced in
 d51fc41b90784f71454c2478d153dab9b53ae690  

        Patch:

 static
 void
 exec(const Ast *ast) {
 //printf("executing "); pn(ast);
 	Value *v;
 	switch(ast->class) {
 	case N_BLOCK:
 		block(ast);
 		return;
 	case N_IF:
 		ifstat(ast);
 		return;
 	case N_WHILE:
 		whilestat(ast);
 		return;
 	case N_DECLARATION:
 		declaration(ast);
 		return;
+	case N_FUNCTION:
+		return;
 	case N_RETURN:
 		returnstat(ast);
 		return;
 	case N_CALL:
 	case N_ASSIGNMENT:
 	case N_IDENTIFIER:
 	case N_NEG:
 	case N_NOT:
 	case N_EQ:
 	case N_NEQ:
 	case N_AND:
 	case N_IOR:
 	case N_XOR:
 	case N_LT:
 	case N_LE:
 	case N_GE:
 	case N_GT:
 	case N_ADD:
 	case N_SUB:
 	case N_MUL:
 	case N_DIV:
 	case N_POW:
 	case N_MOD:
 	case N_BOOLEAN:
 	case N_INTEGER:
 	case N_FLOAT:
 	case N_STRING:
 	case N_SET:
 	case N_R:
 		v = eval(ast);
 do { print_tree(stdout, ast); printf(" evaluates to "); pv(v); } while(0);
 		value_free(v);
 		return;
 	}
 printf("EXECFAIL %d ", ast->class); pn(ast);
 	assert(false && "should not be reached");
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>
